void mainImage(out vec4 fragColor, in vec2 fragCoord) 
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;

    uv.y += sin(iTime + uv.x * 10.0) * 0.1;
    uv.x += sin(iTime * 0.5 + uv.y * 20.0) * 0.05;
    vec3 color = vec3(sin(iTime), cos(iTime * 0.5), sin(iTime * 0.2));
    vec3 color2 = vec3(sin(iTime * 0.7), cos(iTime * 0.2), sin(iTime * 0.3));

    vec3 outColor = mix(color, color2, uv.x);
    // Output to screen
    fragColor = vec4(outColor, 1.0);
}
